package protocol

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"os"
)

//go:embed codes.json
var embeddedCodes []byte

// Codes maps Albion event/operation names to their numeric codes.
//
// Codes change with game patches, so they are NEVER hardcoded in Go: the
// embedded codes.json (generated by tools/gencodes) is the default, and users
// can drop an override file in the config dir to hotfix after a patch.
type Codes struct {
	Source     string            `json:"source"`
	Events     map[string]uint16 `json:"events"`
	Operations map[string]uint16 `json:"operations"`

	eventByCode map[uint16]string
	opByCode    map[uint16]string
}

// DefaultCodes returns the codes embedded at build time.
func DefaultCodes() *Codes {
	c, err := ParseCodes(embeddedCodes)
	if err != nil {
		panic(fmt.Sprintf("embedded codes.json is invalid: %v", err))
	}
	return c
}

// LoadCodes reads an override codes file (same format as codes.json).
func LoadCodes(path string) (*Codes, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return ParseCodes(b)
}

// ParseCodes parses a codes.json document.
func ParseCodes(b []byte) (*Codes, error) {
	var c Codes
	if err := json.Unmarshal(b, &c); err != nil {
		return nil, err
	}
	if len(c.Events) == 0 {
		return nil, fmt.Errorf("codes: no events")
	}
	c.eventByCode = invert(c.Events)
	c.opByCode = invert(c.Operations)
	return &c, nil
}

func invert(m map[string]uint16) map[uint16]string {
	out := make(map[uint16]string, len(m))
	for name, code := range m {
		out[code] = name
	}
	return out
}

func (c *Codes) EventName(code uint16) (string, bool) {
	n, ok := c.eventByCode[code]
	return n, ok
}

func (c *Codes) EventCode(name string) (uint16, bool) {
	v, ok := c.Events[name]
	return v, ok
}

func (c *Codes) OperationName(code uint16) (string, bool) {
	n, ok := c.opByCode[code]
	return n, ok
}

func (c *Codes) OperationCode(name string) (uint16, bool) {
	v, ok := c.Operations[name]
	return v, ok
}
